{
  "name": "@nospt/open-copilot-bridge",
  "version": "0.1.1",
  "description": "OpenCode plugin that bridges GitHub Copilot Enterprise features (org instructions, custom agents, path-specific instructions, MCP configs) into OpenCode",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "type": "module",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    },
    "./server": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    },
    "./tui": {
      "import": "./dist/tui.js",
      "types": "./dist/tui.d.ts"
    }
  },
  "scripts": {
    "postinstall": "bash scripts/setup-test-stubs.sh",
    "build": "tsc",
    "prepublishOnly": "tsc",
    "typecheck": "tsc --noEmit",
    "test": "bun test",
    "docs:dev": "vitepress dev docs",
    "docs:build": "vitepress build docs",
    "docs:preview": "vitepress preview docs"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "github-copilot",
    "copilot-enterprise",
    "copilot-bridge"
  ],
  "license": "MIT",
  "author": "Luis Andre <luisandre98@gmail.com> (https://github.com/luiscga)",
  "repository": {
    "type": "git",
    "url": "https://github.com/nosportugal/open-copilot-bridge.git"
  },
  "bugs": {
    "url": "https://github.com/nosportugal/open-copilot-bridge/issues"
  },
  "homepage": "https://github.com/nosportugal/open-copilot-bridge#readme",
  "devDependencies": {
    "@opencode-ai/plugin": "latest",
    "@types/bun": "latest",
    "@types/picomatch": "^4.0.3",
    "typescript": "^5.8.0",
    "vitepress": "^1.6.4"
  },
  "dependencies": {
    "picomatch": "^4.0.0",
    "yaml": "^2.7.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "*",
    "@opentui/core": ">=0.1.97",
    "@opentui/solid": ">=0.1.97"
  },
  "peerDependenciesMeta": {
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    }
  },
  "publishConfig": {
    "access": "public"
  }
}
